#include <oa/core/fnMatrix.h>
#include <oa/runtime/engine.h>

#include <array>
#include <cmath>
#include <cstdio>
#include <utility>

int main() {
	oa::EngineConfig config;
	config.appName = "ExampleCoreMatrixAdd";
	config.presentationMode = oa::PresentationMode::None;

	auto created = oa::Engine::create(config);
	if (not created.isOk()) {
		std::fprintf(stderr, "Engine creation failed: %s\n",
			created.getStatus().getMessage().cStr());
		return 1;
	}
	auto engine = std::move(created).getValue();

	auto one = oa::FnMatrix::ones({2, 3});
	auto two = oa::FnMatrix::full({2, 3}, 2.0F);
	auto sum = oa::FnMatrix::add(one, two);

	auto submitted = engine->submit();
	if (not submitted.isOk()) return 1;
	if (not engine->wait(submitted.getValue()).isOk()) return 1;

	std::array<oa::F32, 6> values{};
	if (not oa::FnMatrix::copyToHost(
		sum, values.data(), sizeof(values)).isOk()) return 1;
	for (const oa::F32 value : values) {
		if (std::abs(value - 3.0F) > 1.0e-6F) return 1;
	}

	std::puts("[3, 3, 3, 3, 3, 3]");
	return 0;
}

#include <oa/audio/fnAudio.h>
#include <oa/core/fnMatrix.h>
#include <oa/runtime/engine.h>

#include <array>
#include <cmath>
#include <cstdio>
#include <utility>

int main() {
	oa::EngineConfig config;
	config.appName = "ExampleAudioClip";
	config.presentationMode = oa::PresentationMode::None;

	auto created = oa::Engine::create(config);
	if (not created.isOk()) return 1;
	auto engine = std::move(created).getValue();

	oa::Audio audio(
		oa::FnMatrix::full({1, 8}, 0.75F),
		48'000U,
		oa::AudioChannelLayout::Mono
	);
	auto clipped = oa::FnAudio::clip(audio, -0.5F, 0.5F);

	auto submitted = engine->submit();
	if (not submitted.isOk()) return 1;
	if (not engine->wait(submitted.getValue()).isOk()) return 1;
	if (not clipped.validate() || clipped.sampleRate() != 48'000U) return 1;

	std::array<oa::F32, 8> values{};
	if (not oa::FnMatrix::copyToHost(
		clipped.asMatrix(), values.data(), sizeof(values)).isOk()) return 1;
	for (const oa::F32 value : values) {
		if (std::abs(value - 0.5F) > 1.0e-6F) return 1;
	}

	std::puts("8 mono samples clipped to 0.5");
	return 0;
}

#include <oa/core/fnMatrix.h>
#include <oa/core/image.h>
#include <oa/runtime/engine.h>
#include <oa/vision/fnImage.h>

#include <array>
#include <cmath>
#include <cstdio>
#include <utility>

int main() {
	oa::EngineConfig config;
	config.appName = "ExampleVisionResize";
	config.presentationMode = oa::PresentationMode::None;

	auto created = oa::Engine::create(config);
	if (not created.isOk()) return 1;
	auto engine = std::move(created).getValue();

	oa::Image image(
		oa::FnMatrix::full({1, 3, 2, 2}, 0.25F),
		oa::ImageLayout::Nchw,
		oa::ImageFormat::Rgb);
	auto resized = oa::FnImage::resize(image, 4, 3);

	auto submitted = engine->submit();
	if (not submitted.isOk()) return 1;
	if (not engine->wait(submitted.getValue()).isOk()) return 1;
	if (not resized.validate() || resized.width() != 4 || resized.height() != 3) {
		return 1;
	}

	std::array<oa::F32, 36> values{};
	if (not oa::FnMatrix::copyToHost(
		resized.asMatrix(), values.data(), sizeof(values)).isOk()) return 1;
	for (const oa::F32 value : values) {
		if (std::abs(value - 0.25F) > 1.0e-6F) return 1;
	}

	std::puts("RGB NCHW image resized from 2x2 to 4x3");
	return 0;
}

#include <oa/core/fnMatrix.h>
#include <oa/crypto/fnHash.h>
#include <oa/crypto/keccak.h>
#include <oa/runtime/engine.h>

#include <array>
#include <cstdio>
#include <cstring>
#include <utility>

int main() {
	oa::EngineConfig config;
	config.appName = "ExampleCryptoShake256";
	config.presentationMode = oa::PresentationMode::None;

	auto created = oa::Engine::create(config);
	if (not created.isOk()) return 1;
	auto engine = std::move(created).getValue();

	constexpr std::array<oa::U8, 15> messages{
		'a', 'l', 'p', 'h', 'a',
		'b', 'r', 'a', 'v', 'o',
		'c', 'r', 'y', 'p', 't',
	};
	auto input = oa::FnMatrix::fromBytes(
		oa::Span<const oa::U8>(messages.data(), messages.size()),
		{3, 5},
		oa::ScalarType::UInt8
	);
	auto digests = oa::FnHash::shake256(input, 32);

	auto submitted = engine->submit();
	if (not submitted.isOk()) return 1;
	if (not engine->wait(submitted.getValue()).isOk()) return 1;

	std::array<oa::U8, 96> gpu{};
	std::array<oa::U8, 96> cpu{};
	if (not oa::FnMatrix::copyToHost(
		digests, gpu.data(), gpu.size()).isOk()) return 1;
	for (oa::Usize row = 0; row < 3; ++row) {
		oa::shake256(
			messages.data() + row * 5,
			5,
			cpu.data() + row * 32,
			32
		);
	}
	if (std::memcmp(gpu.data(), cpu.data(), gpu.size()) != 0) return 1;

	std::puts("3 GPU SHAKE-256 digests match the CPU oracle");
	return 0;
}

#include <oa/runtime/engine.h>
#include <oa/ui/plot/plot.h>

#include <array>
#include <cstdio>
#include <utility>

int main() {
	oa::EngineConfig engineConfig;
	engineConfig.appName = "ExamplePlotLine";
	engineConfig.presentationMode = oa::PresentationMode::Headless;

	auto created = oa::Engine::create(engineConfig);
	if (not created.isOk()) return 1;
	auto engine = std::move(created).getValue();

	oa::plot::Figure figure({
		.title = "training loss",
		.width = 360,
		.height = 240,
		.theme = oa::plot::Theme::Dark,
	});
	constexpr std::array<oa::F32, 6> loss{1.0F, 0.72F, 0.51F, 0.38F, 0.29F, 0.23F};
	figure.ax(0, 0).xLabel("step");
	figure.ax(0, 0).yLabel("loss");
	figure.ax(0, 0).plot(loss);

	auto rendered = figure.render(*engine);
	if (not rendered.isOk()) return 1;
	auto image = std::move(rendered).getValue();
	if (not image.validate() || image.width() != 360 || image.height() != 240) {
		return 1;
	}

	std::puts("rendered a 360x240 training-loss figure");
	return 0;
}
